let data = $input.first().json;
if (data && typeof data.output === 'object' && !Array.isArray(data.output)) data = data.output;
function fail(message) { throw new Error(`[skills] ${message}`); }
function isObject(value) { return value !== null && typeof value === 'object' && !Array.isArray(value); }
function exact(object, required) {
  if (!isObject(object)) fail('Output must be one JSON object.');
  const actual=Object.keys(object), missing=required.filter((key)=>!(key in object)), extra=actual.filter((key)=>!required.includes(key));
  if (missing.length) fail(`Missing keys: ${missing.join(', ')}`);
  if (extra.length) fail(`Unexpected keys: ${extra.join(', ')}`);
}
exact(data,['requirements','limited_data_reason','skill_rating']);
if (!Array.isArray(data.requirements)) fail('requirements must be an array.');
if (data.limited_data_reason !== null && (typeof data.limited_data_reason !== 'string' || data.limited_data_reason.trim()==='')) fail('limited_data_reason must be null or a non-empty string.');
if (!Number.isInteger(data.skill_rating) || data.skill_rating<1 || data.skill_rating>5) fail('skill_rating must be an integer from 1 through 5.');
if (data.requirements.length===0) {
  if (data.limited_data_reason===null || data.skill_rating!==1) fail('No requirements requires a limited_data_reason and skill_rating 1.');
  return [{json:data}];
}
if (data.limited_data_reason!==null) fail('limited_data_reason must be null when requirements are present.');

const requiredFields=['requirement','priority','explicitness','outcome','central','mandatory_credential','resume_evidence'];
const seen=new Set();
for (const requirement of data.requirements) {
  exact(requirement,requiredFields);
  if (typeof requirement.requirement!=='string' || requirement.requirement.trim()==='') fail('Every requirement needs a non-empty requirement statement.');
  if (!['MUST','NICE'].includes(requirement.priority)) fail('Invalid requirement priority.');
  if (!['EXPLICIT','IMPLICIT'].includes(requirement.explicitness)) fail('Invalid requirement explicitness.');
  if (!['DIRECT','GAP','TRANSFERABLE'].includes(requirement.outcome)) fail('Invalid requirement outcome.');
  if (typeof requirement.central!=='boolean' || typeof requirement.mandatory_credential!=='boolean') fail('central and mandatory_credential must be boolean.');
  if (typeof requirement.resume_evidence!=='string' || requirement.resume_evidence.trim()==='') fail('Every requirement needs resume_evidence.');
  if ((requirement.central || requirement.mandatory_credential) && requirement.priority!=='MUST') fail('Central or mandatory-credential requirements must be MUST.');
  if (requirement.mandatory_credential && requirement.explicitness!=='EXPLICIT') fail('Mandatory credentials must be explicit requirements.');
  const key=requirement.requirement.trim().toLowerCase();
  if (seen.has(key)) fail(`Duplicate canonical requirement: ${requirement.requirement}`);
  seen.add(key);
}

const total=data.requirements.reduce((sum,requirement)=>sum+(requirement.priority==='MUST'?2:1),0);
const earned=data.requirements.reduce((sum,requirement)=>{
  const available=requirement.priority==='MUST'?2:1;
  return sum+(requirement.outcome==='DIRECT'?available:requirement.outcome==='TRANSFERABLE'?available*0.5:0);
},0);
const coverage=earned/total;
const base=coverage>=0.8?5:coverage>=0.6?4:coverage>=0.4?3:coverage>=0.2?2:1;
const centralGaps=data.requirements.filter((requirement)=>requirement.priority==='MUST'&&requirement.outcome==='GAP'&&requirement.central).length;
const credentialGap=data.requirements.some((requirement)=>requirement.priority==='MUST'&&requirement.outcome==='GAP'&&requirement.mandatory_credential);
const cap=credentialGap||centralGaps>=2?2:centralGaps===1?3:5;
const expected=Math.min(base,cap);
if (data.skill_rating!==expected) fail(`skill_rating must be ${expected} from ${(coverage*100).toFixed(1)}% weighted coverage and structured cap fields.`);
return [{json:data}];

const envelope = $('When Executed by Another Workflow').first().json;
const analysis = $input.first().json;
const jobId = String(envelope.job?.job_id || '').trim();
if (!/^\d{6,20}$/.test(jobId)) throw new Error('[skills] Missing canonical LinkedIn job_id.');

const requirements = Array.isArray(analysis.requirements) ? analysis.requirements : [];
const prefix = (requirement) => `[${requirement.priority}][${requirement.explicitness}][${requirement.outcome}]`;
const render = (requirement) => `${prefix(requirement)} ${requirement.requirement} — ${requirement.resume_evidence}`;
const skillMatches = requirements.filter((requirement) => requirement.outcome === 'DIRECT').map(render);
const skillMisses = requirements.filter((requirement) => requirement.outcome === 'GAP').map(render);
const skillTranslations = requirements.filter((requirement) => requirement.outcome === 'TRANSFERABLE').map(render);
if (requirements.length === 0) skillMisses.push(`Limited data available: ${analysis.limited_data_reason}`);
const centralGaps = requirements.filter((requirement) => requirement.outcome === 'GAP' && requirement.central);
const credentialGaps = requirements.filter((requirement) => requirement.outcome === 'GAP' && requirement.mandatory_credential);
const capNotes = [];
if (credentialGaps.length) capNotes.push(`mandatory credential gap: ${credentialGaps.map((item) => item.requirement).join('; ')}`);
if (centralGaps.length) capNotes.push(`${centralGaps.length} central MUST gap(s): ${centralGaps.map((item) => item.requirement).join('; ')}`);
if (capNotes.length) skillMisses.push(`[RATING CAP] ${capNotes.join(' • ')}`);
const result = {
  job_id: jobId,
  skill_matches: skillMatches,
  skill_misses: skillMisses,
  skill_translations: skillTranslations,
  skill_rating: analysis.skill_rating,
  skill_rating_rationale: capNotes.length ? capNotes.join(' • ') : 'No cap applied; rating derived from weighted requirement coverage.',
};
return [{json:{...envelope,results:{...(envelope.results||{}),skills:result}}}];
